// Plausible static QR ticket — <lp-qr size="140" seed="7">
(function(){
if (customElements.get('lp-qr')) return;
class LpQr extends HTMLElement {
  static get observedAttributes(){ return ['size','seed','fg','bg']; }
  connectedCallback(){ this._dd(); this._render(); }
  attributeChangedCallback(a, o, n){ if (o === n) return; this._dd(); this._render(); }
  _dd(){
    if (this.__mo) return;
    this.__mo = new MutationObserver(() => {
      const s = this.querySelectorAll(':scope > svg');
      for (let i = 0; i < s.length - 1; i++) s[i].remove();
    });
    this.__mo.observe(this, { childList: true });
  }
  _render(){
    if (this.closest && this.closest('x-dc')) { this.textContent = ''; return; } // never render inside the raw template snapshot
    const size = parseFloat(this.getAttribute('size') || 140);
    let s = parseInt(this.getAttribute('seed') || 7);
    const fg = this.getAttribute('fg') || '#191919';
    const bg = this.getAttribute('bg') || '#ffffff';
    const N = 25;
    const rnd = () => { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff; };
    const grid = Array.from({length: N}, () => Array(N).fill(0));
    const finder = (r, c) => {
      for (let y = 0; y < 7; y++) for (let x = 0; x < 7; x++) {
        const ring = Math.max(Math.abs(y-3), Math.abs(x-3));
        grid[r+y][c+x] = (ring === 3 || ring <= 1) ? 1 : 0;
      }
    };
    finder(0,0); finder(0,N-7); finder(N-7,0);
    for (let i = 8; i < N-8; i++) { grid[6][i] = i % 2 === 0 ? 1 : 0; grid[i][6] = i % 2 === 0 ? 1 : 0; }
    // alignment pattern bottom-right
    for (let y = 0; y < 5; y++) for (let x = 0; x < 5; x++) {
      const ring = Math.max(Math.abs(y-2), Math.abs(x-2));
      grid[N-9+y][N-9+x] = (ring === 2 || ring === 0) ? 1 : 0;
    }
    const reserved = (r,c) => (r<8&&c<8)||(r<8&&c>=N-8)||(r>=N-8&&c<8)||r===6||c===6||(r>=N-9&&r<N-4&&c>=N-9&&c<N-4);
    for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) if (!reserved(r,c)) grid[r][c] = rnd() < 0.47 ? 1 : 0;
    const m = size / (N + 4); // quiet zone 2 modules
    let path = '';
    for (let r = 0; r < N; r++) for (let c = 0; c < N; c++) if (grid[r][c])
      path += 'M' + ((c+2)*m).toFixed(2) + ' ' + ((r+2)*m).toFixed(2) + 'h' + m.toFixed(2) + 'v' + m.toFixed(2) + 'h-' + m.toFixed(2) + 'z';
    this.style.display = 'inline-flex'; this.style.lineHeight = '0'; this.style.flexShrink = '0';
    this.innerHTML = '<svg width="' + size + '" height="' + size + '" viewBox="0 0 ' + size + ' ' + size + '" style="display:block"><rect width="' + size + '" height="' + size + '" fill="' + bg + '" rx="6"/><path d="' + path + '" fill="' + fg + '"/></svg>';
  }
}
if (!customElements.get('lp-qr')) customElements.define('lp-qr', LpQr);
})();
